function passwordRecoveryScreen(mode){
  const reset=mode==='reset',panel=$('.login-form');
  panel.innerHTML=`<div class="meta">ZUGANG WIEDERHERSTELLEN</div><h2>${reset?'Neues Passwort.':'Passwort vergessen?'}</h2><p>${reset?'Wählen Sie ein neues Passwort mit mindestens 12 Zeichen. Nach dem Speichern melden Sie sich damit an.':'Geben Sie die E-Mail-Adresse Ihres Zugangs ein. Sie erhalten einen Link, der 30 Minuten gültig ist.'}</p><form class="form" id="recovery-form">${reset?field('Neues Passwort','password','','password','Mindestens 12 Zeichen.','required minlength="12" autocomplete="new-password"')+field('Passwort wiederholen','confirmation','','password','','required minlength="12" autocomplete="new-password"'):field('E-Mail-Adresse','email','','email','','required autocomplete="username"')}<div class="error" role="alert"></div><button class="es-btn es-btn--primary" type="submit">${reset?'Passwort speichern':'Link anfordern'} ${icon('arrow_forward')}</button></form><div class="form-foot"><button type="button" class="link" data-action="recovery-login">Zur Anmeldung</button>${reset?'<button type="button" class="link" data-action="recovery-new">Neuen Link anfordern</button>':''}</div>`;
  bind('recovery-login',()=>{recoveryToken=null;login(false);});
  bind('recovery-new',()=>{recoveryToken=null;passwordRecoveryScreen('forgot');});
  const form=$('#recovery-form');
  form.onsubmit=async e=>{
    e.preventDefault();const submit=$('[type="submit"]',form);submit.disabled=true;$('.error',form).textContent='';
    try{
      const data=Object.fromEntries(new FormData(form));
      if(reset&&data.password!==data.confirmation)throw Error('Die beiden Passwörter stimmen nicht überein.');
      const result=await api(reset?'password.reset':'password.forgot',reset?{...data,token:recoveryToken}:data);
      recoveryToken=null;
      panel.innerHTML=`<div class="meta">${reset?'PASSWORT GESPEICHERT':'ANFRAGE ABGESCHLOSSEN'}</div><h2>${reset?'Zugang wieder bereit.':'Postfach prüfen.'}</h2><p role="status">${reset?'Ihr Passwort wurde geändert. Alle bisherigen Sitzungen und Wiederherstellungslinks sind jetzt ungültig. Melden Sie sich mit Ihrem neuen Passwort an.':esc(result.message)}</p><button type="button" class="es-btn es-btn--primary" data-action="recovery-login">Zur Anmeldung ${icon('arrow_forward')}</button>${reset?'':'<div class="form-foot"><button type="button" class="link" data-action="recovery-new">Andere E-Mail-Adresse verwenden</button></div>'}`;
      bind('recovery-login',()=>login(false));bind('recovery-new',()=>passwordRecoveryScreen('forgot'));
    }catch(error){$('.error',form).textContent=error.message;}finally{submit.disabled=false;}
  };
  $('input',form)?.focus();
}
