function configureCodeFontSize(){
  const key='entrosphere:code-font-size:'+user.id,min=10,max=28,defaultSize=13;
  let size=defaultSize;try{const stored=Number(localStorage.getItem(key));if(Number.isInteger(stored)&&stored>=min&&stored<=max)size=stored;}catch{}
  const apply=()=>{
    $('#code-editor').style.setProperty('--code-font-size',size+'px');
    const reset=$('[data-action="code-font-reset"]');reset.textContent=size+' px';reset.setAttribute('aria-label',`Code-Schriftgröße ${size} Pixel. Auf ${defaultSize} Pixel zurücksetzen`);
    $('[data-action="code-font-smaller"]').disabled=size===min;$('[data-action="code-font-larger"]').disabled=size===max;
    editor?.requestMeasure();
  };
  const change=value=>{size=Math.max(min,Math.min(max,value));apply();try{localStorage.setItem(key,String(size));}catch{}};
  bind('code-font-smaller',()=>change(size-1));bind('code-font-larger',()=>change(size+1));bind('code-font-reset',()=>change(defaultSize));apply();
}
