  bind('converter-download',()=>{if(!output.value)throw Error('Erst Daten umwandeln.');download(new Blob([output.value],{type:to.value==='json'?'application/json':to.value==='xml'?'application/xml':'text/plain;charset=utf-8'}),`daten.${to.value}`);});
