  $('#chat-compose').onsubmit=async e=>{e.preventDefault();const body=$('#message').value.trim(),file=selectedFile;if(!body&&!file)return;const form=e.target,gid=chatGroup,seq=generation;const controls=$$('button,textarea',form);controls.forEach(c=>c.disabled=true);try{if(file){const data=new FormData();data.set('group',gid);data.set('body',body);data.set('file',file);const response=await fetch('/api/?action=chat.upload',{method:'POST',headers:{'X-CSRF-Token':csrf},body:data,credentials:'same-origin'});let result;try{result=await response.json();}catch{throw Error('Der Server hat den Upload abgelehnt. Bitte die Dateigröße prüfen.');}if(!response.ok)throw Error(result.error);}else await api('chat.send',{group:gid,body});if(valid(gid,seq)){$('#message').value='';$('#message').style.height='auto';clearFile();await load();$('#messages').scrollTop=$('#messages').scrollHeight;}}catch(err){toast(err.message,true);}finally{controls.forEach(c=>c.disabled=false);}};
