async function adminStatistics(version){
  const d=await api('admin.overview'),days=[];for(let i=13;i>=0;i--){const day=new Date();day.setUTCDate(day.getUTCDate()-i);const key=day.toISOString().slice(0,10);days.push({day:key,activity:0,runs:0,...d.daily.find(v=>v.day===key)});}const max=Math.max(1,...days.map(d=>d.activity));
  render(`<div class="content">${pageHead('06','Fortschritt wird sichtbar<span class="accent">.</span>','Nutzung im Überblick. Ohne Inhalte aus persönlichen Projekten.')}${stats([['LERNENDE',num(d.counts.users),'Alle Benutzerzugänge'],['PROJEKTE',num(d.counts.projects),'Angelegte Entwicklungsräume'],['AUSFÜHRUNGEN',num(d.counts.runs),'Erfolgreich gestartete Runs'],['AKTIVITÄT',num(days.reduce((s,d)=>s+Number(d.activity),0)),'Ereignisse in den letzten 14 Tagen']])}<div class="two-col" style="margin-top:28px"><section class="panel"><div class="meta">01 // LETZTE 14 TAGE · UTC</div><h2>Aktivität pro Tag.</h2><div class="chart" role="img" aria-label="${esc(days.map(d=>d.day+': '+d.activity+' Ereignisse').join(', '))}">${days.map(d=>`<div class="chart-column"><b>${num(d.activity)}</b><div class="chart-bar" style="height:${Math.max(1,d.activity/max*80)}%"></div><span>${d.day.slice(8)}.${d.day.slice(5,7)}</span></div>`).join('')}</div></section><section class="panel"><div class="meta">02 // SPRACHEN</div><h2>Code in Bewegung.</h2>${d.languages.length?d.languages.map(l=>`<div class="activity-item"><strong>${esc(l.language.toUpperCase())}</strong><span class="meta">${num(l.runs)} RUNS</span></div>`).join(''):'<div class="notice">Hier erscheinen Sprachen, sobald Code ausgeführt wird.</div>'}</section></div><div class="section-head"><h2>Nutzungsprotokoll</h2><span class="meta">LETZTE 30 EREIGNISSE</span></div><div class="table-wrap" style="margin-top:20px"><table><thead><tr><th>Zeit</th><th>Benutzer</th><th>Ereignis</th></tr></thead><tbody>${d.events.map(e=>`<tr><td>${datetime(e.created_at)}</td><td>${esc(e.name||'Gelöschter Zugang')}</td><td>${EVENTS[e.event]||'Workspace-Aktivität'}</td></tr>`).join('')}</tbody></table></div></div>`,version);
}
