const MAIL_STATUSES={pending:'Vorbereitet',sending:'Wird gesendet',sent:'Von Mailjet angenommen',failed:'Abgelehnt',uncertain:'Status unklar',expired:'Abgelaufen',cancelled:'Zugang geändert'};
