function profilePhoto(user){return '/profile-photo.php?'+new URLSearchParams({id:user.id,v:user.profile?.picture_version||0});}
function updateAccount(){
  const account=$('.account');if(!account||!user)return;$('.name',account).textContent=user.name;$('small',account).textContent=roleLabel(user.role);$$('[data-profile-greeting]').forEach(el=>el.textContent=user.name);$$('.message-own .message-head strong').forEach(el=>el.textContent=user.name);$$('.message-own .message-avatar').forEach(el=>el.textContent=initials(user.name));const avatar=$('.avatar',account);avatar.classList.toggle('has-photo',!!user.profile?.has_picture);avatar.innerHTML=user.profile?.has_picture?`<img class="profile-avatar" src="${profilePhoto(user)}" alt="">`:`<span class="avatar-label">${esc(initials(user.name))}</span><span class="avatar-icon">${icon('person')}</span>`;
}
async function profileDialog(){
  const fresh=await api('profile');user=fresh.user;updateAccount();const p=user.profile;let photo,wantsPassword=false,wantsAi=false;
  const linkRow=(link={})=>`<div class="profile-link-row">${field('Bezeichnung','link-label',link.label||'','text','Zum Beispiel LinkedIn oder Blog.','maxlength="60"')}${field('URL','link-url',link.url||'','url','','required maxlength="500" placeholder="https://"')}${ib('close','remove-profile-link','Link entfernen')}</div>`;
  try{await modal('Ihr Profil',`<div class="lab-tabs" role="tablist"><button type="button" role="tab" aria-selected="true">Profil</button>${flags.ai?button('KI-Zugänge','profile-ai','secondary','key'):''}</div><div class="profile-grid"><section class="profile-photo-editor"><div class="meta">PROFILBILD</div><div class="profile-crop" tabindex="0" role="group" aria-label="Bildausschnitt: ziehen oder Pfeiltasten verwenden"><canvas width="192" height="192" hidden></canvas><span class="profile-photo-placeholder"></span></div><input type="file" accept="image/jpeg,image/png,image/webp,image/gif,image/avif" hidden><button type="button" class="es-btn es-btn--sm es-btn--secondary" data-photo-choose>${icon('upload')}Bild auswählen</button><p class="profile-photo-hint" role="status">Bild hier ablegen oder auswählen.</p><div class="profile-photo-tools" hidden><label class="field"><span>Zoom</span><input type="range" min="1" max="3" step="0.01" value="1" data-photo-zoom></label><div class="profile-photo-actions"><button type="button" class="icon-btn" data-photo-rotate aria-label="Bild drehen" title="Bild drehen">${icon('rotate_right')}</button><button type="button" class="icon-btn" data-photo-reset aria-label="Ausschnitt zurücksetzen" title="Ausschnitt zurücksetzen">${icon('restart_alt')}</button><button type="button" class="icon-btn" data-photo-remove aria-label="Profilbild entfernen" title="Profilbild entfernen">${icon('delete')}</button></div></div><small class="muted">Zum Hochladen ein Bild hier ablegen oder auswählen. JPG, PNG, WebP, GIF oder AVIF · bis 10 MB. Gespeichert wird nur Ihr Ausschnitt.</small></section><section class="form"><div class="form-grid">${field('Vorname','first_name',p.first_name,'text','','maxlength="80" autocomplete="given-name"')}${field('Nachname','last_name',p.last_name,'text','','maxlength="80" autocomplete="family-name"')}</div>${field('Anzeigename','name',user.name,'text','So erscheinen Sie im Workspace und Chat.','required maxlength="120" autocomplete="nickname"')}<div class="profile-role"><span>${esc(roleLabel(user.role))}</span><small>Ihre Rolle wird von der Kursleitung verwaltet.</small></div><label class="field"><span>Über mich</span><textarea name="bio" rows="4" maxlength="2000" placeholder="Ein paar Worte über Sie, Ihre Interessen oder Ihre Arbeit …">${esc(p.bio)}</textarea></label><div class="section-head"><h3>Ihre Links</h3>${button('Link hinzufügen','add-profile-link','secondary','add')}</div><div id="profile-links">${p.urls.map(linkRow).join('')}</div><section class="profile-sharing"><h3>Profil im Team anzeigen</h3><label class="team-consent"><input type="checkbox" name="team_consent" ${p.team_consent?'checked':''}><span>${esc(p.consent_text)}</span></label><p class="muted">Freiwillig. Sie können die Freigabe hier jederzeit für die Zukunft widerrufen. Ohne Freigabe bleibt Ihr Profil für andere Gruppenmitglieder unsichtbar; Ihre Lernumgebung können Sie weiterhin nutzen.</p><small class="muted">Freigaben gelten für Ihre aktuellen Lerngruppen. E-Mail-Adresse und Kontoeinstellungen werden nicht angezeigt.</small></section><div class="profile-password">${button('Passwort ändern','profile-password','secondary','lock')}</div></section></div>`,async data=>{const labels=data.getAll('link-label'),urls=data.getAll('link-url');const result=await api('profile.save',{name:data.get('name'),first_name:data.get('first_name'),last_name:data.get('last_name'),bio:data.get('bio'),urls:urls.map((url,i)=>({url,label:labels[i]})),picture:await photo.value(),version:p.version,team_consent:data.has('team_consent')});user=result.user;updateAccount();toast('Ihr Profil wurde aktualisiert.');},'Profil speichern',{className:'profile-dialog',after:dialog=>{
    photo=mountProfilePicture($('.profile-photo-editor',dialog),p.has_picture?profilePhoto(user):null,initials(user.name));const links=$('#profile-links',dialog),add=$('[data-action="add-profile-link"]',dialog);const bindLinks=()=>{bind('remove-profile-link',(e,el)=>{el.closest('.profile-link-row').remove();add.disabled=$$('.profile-link-row',links).length>=8;},links);add.disabled=$$('.profile-link-row',links).length>=8;};bindLinks();bind('add-profile-link',()=>{if($$('.profile-link-row',links).length>=8)return;links.insertAdjacentHTML('beforeend',linkRow());bindLinks();$('.profile-link-row:last-child input',links).focus();},dialog);
    let fieldsDirty=false;bind('profile-ai',()=>{if(fieldsDirty||photo.dirty){$('.error',dialog).textContent='Bitte Profiländerungen zuerst speichern.';return;}wantsAi=true;$('[data-action="close-modal"]',dialog).click();},dialog);$('form',dialog).addEventListener('input',()=>fieldsDirty=true);bind('profile-password',()=>{if(fieldsDirty||photo.dirty){$('.error',dialog).textContent='Bitte Ihre Profiländerungen zuerst speichern. Danach können Sie hier Ihr Passwort ändern.';return;}wantsPassword=true;$('[data-action="close-modal"]',dialog).click();},dialog);
  }});}finally{photo?.destroy();}
  if(wantsPassword)await passwordModal(false);if(wantsAi)await connectionDialog();
}

function teamImage(person,group){return person.has_picture?`<img src="/profile-photo.php?${esc(new URLSearchParams({id:person.id,group,v:person.picture_version}))}" alt="" loading="lazy">`:`<span>${esc(initials(person.name))}</span>`;}
async function team(version){
  let data=await api('team'),group='',disposed=false,busy=false,selected=null,signature='';
  const preference='entrosphere:team-group:'+user.id;
  let remembered='';try{remembered=sessionStorage.getItem(preference)||'';}catch{}
  group=data.groups.find(g=>g.id===(chatGroup||teachingGroup||projects.find(p=>p.id===activeProject)?.group_id||remembered))?.id||data.groups[0]?.id||'';
  if(!render(`<div class="content">${pageHead('07','Ihr Team<span class="accent">.</span>','Menschen kennenlernen. Gemeinsam weiterkommen.')}<div class="toolbar"><label class="field"><span>Lerngruppe</span><select id="team-group" ${data.groups.length?'':'disabled'}>${data.groups.map(g=>`<option value="${esc(g.id)}" ${g.id===group?'selected':''}>${esc(g.name)}</option>`).join('')||'<option>Keine Lerngruppe</option>'}</select></label>${button('Mein Profil','team-own','secondary','person')}</div><p class="muted">Hier erscheinen nur freiwillig freigegebene Profile dieser Lerngruppe.</p><div id="team-members" aria-live="polite"></div><p id="team-status" class="muted" role="status"></p></div>`,version))return;
  const draw=()=>{const target=$('#team-members');if(!target)return;const next=JSON.stringify([group,data.members]);if(next===signature)return;signature=next;target.innerHTML=data.members.length?`<div class="team-grid">${data.members.map(p=>`<button class="team-card" type="button" data-member="${esc(p.id)}"><span class="team-avatar">${teamImage(p,group)}</span><span><strong>${esc(p.name)}</strong><small>${esc(roleLabel(p.role))}</small></span>${icon('arrow_forward')}</button>`).join('')}</div>`:empty(group?'Noch keine freigegebenen Profile':'Noch keine Lerngruppe',group?'Mitglieder können ihr Profil über ihren Namen in der Navigation freigeben.':'Ihre Kursleitung kann Sie einer Lerngruppe zuordnen.','groups');$$('[data-member]',target).forEach(el=>el.onclick=()=>showMember(el.dataset.member));};
  const hideMember=()=>{if(!selected)return;const body=$('#modal .dialog-body');if(body)body.innerHTML=empty('Profil nicht mehr verfügbar','Die Freigabe oder Gruppenzugehörigkeit wurde geändert.','lock');};
  const refresh=async()=>{if(disposed||busy||document.hidden)return;busy=true;const current=group;try{const result=await get('team',group?{group}:{});if(disposed||current!==group)return;data=result;draw();$('#team-status').textContent='';if(selected){const id=selected;try{const result=await get('team.profile',{group,id});if(!disposed&&selected===id)paintProfile(result.profile);}catch{if(selected===id)hideMember();}}}catch(e){if(!disposed){data.members=[];draw();hideMember();$('#team-status').textContent=e.message;}}finally{busy=false;}};
  function paintProfile(p){const body=$('#modal .dialog-body');if(!body||!selected)return;body.innerHTML=`<div class="team-profile-heading"><div class="team-avatar team-avatar--large">${teamImage(p,group)}</div><div><h3>${esc(p.name)}</h3><p class="muted">${esc(roleLabel(p.role))}${p.first_name||p.last_name?' · '+esc([p.first_name,p.last_name].filter(Boolean).join(' ')):''}</p></div></div>${p.bio?`<p class="team-bio">${esc(p.bio)}</p>`:'<p class="muted">Noch keine Beschreibung hinterlegt.</p>'}${p.urls.length?`<div class="team-links">${p.urls.map(link=>`<a href="${esc(link.url)}" target="_blank" rel="noopener noreferrer">${esc(link.label)} ${icon('open_in_new')}</a>`).join('')}</div>`:''}`;}
  async function showMember(id){try{const result=await get('team.profile',{group,id});if(disposed)return;selected=id;try{await modal('Team-Profil','',async()=>{},'Schließen',{after:dialog=>{$('[data-action="close-modal"]',dialog.querySelector('.dialog-foot')).hidden=true;paintProfile(result.profile);}});}finally{selected=null;}}catch(e){toast(e.message,true);}}
  bind('team-own',()=>profileDialog().then(refresh));$('#team-group').onchange=async e=>{group=e.target.value;chatGroup=group;try{sessionStorage.setItem(preference,group);}catch{}data.members=[];draw();await refresh();};
  const focus=()=>refresh();addEventListener('focus',focus);document.addEventListener('visibilitychange',focus);const timer=setInterval(refresh,15000);disposeTeam=()=>{disposed=true;clearInterval(timer);removeEventListener('focus',focus);document.removeEventListener('visibilitychange',focus);if(selected){hideMember();$('[data-action="close-modal"]',$('#modal'))?.click();}};await refresh();
}

async function labsPage(version){
  if(!render('<div id="labs-root"></div>',version))return;
  const dispose=await mountLabs($('#labs-root'),{api,get,esc,icon,modal,confirm,toast,flags,user,setDirty:value=>{dirty=value;},onProject:pid=>{activeProject=pid;rememberProject(pid);},onView:view=>{labView=view;},onObject:id=>{labObjectId=id;publishPresence();},openCode:(p,o,path)=>{if(p.user_id&&p.user_id!==user.id&&user.role==='teacher'){const group=user.groups.find(g=>teachingGroups.some(t=>t.id===g.id&&t.members.some(m=>m.id===p.user_id)));if(group)sessionStorage.setItem(teachingKey(),JSON.stringify({group:group.id,person:p.user_id}));}if(path)sessionStorage.setItem('file',path);location.hash='editor?project='+p.id+(path?'&file='+encodeURIComponent(path):'');}});
  if(version===routeVersion)disposeLabs=dispose;else dispose();
}
async function adminLabs(version){if(!render('<div id="lab-admin"></div>',version))return;await mountLabAdmin($('#lab-admin'),{api,get,esc,toast});}
async function connectionDialog(){let cleanup,wantsProfile=false;try{await modal('Meine KI-Zugänge','<div class="lab-tabs" role="tablist"><button type="button" role="tab" data-action="back-profile">Profil</button><button type="button" role="tab" aria-selected="true">KI-Zugänge</button></div><div id="personal-connections"></div>',()=>{},'Schließen',{className:'connections-dialog',after:dialog=>{bind('back-profile',()=>{wantsProfile=true;$('[data-action="close-modal"]',dialog).click();},dialog);mountConnections($('#personal-connections',dialog),{api,get,esc,modal,confirm,toast,user}).then(fn=>cleanup=fn).catch(e=>toast(e.message,true));}});}finally{cleanup?.();}if(wantsProfile)await profileDialog();}

function publishPresence(){if(admin||!user||user.access?.allowed===false||document.hidden||user.must_change_password)return;const route=location.hash.slice(1).split('?')[0]||'dashboard';const project=['database','sql-training'].includes(route)?dbProject:['editor','files','graph','data-lab','ai-lab'].includes(route)?activeProject:null;api('presence.touch',{route,project:project||'',file:route==='editor'?activeFile?.path||'':'',object:labObjectId||'',...labView,table:route==='database'?selectedTable||'':route==='sql-training'?$('#training-table')?.value||'':'',mode:route==='sql-training'?$('#training-mode')?.value||'practice':undefined}).catch(()=>{});}
async function followLearner(uid,gid){if(!await leaveDirty())return;const result=await api('presence.open',{user:uid,group:gid});const c=result.context;const params=new URLSearchParams({participant:result.participant,group:result.group});if(c.project){params.set('project',c.project);rememberProject(c.project);}if(c.file)params.set('file',c.file);if(c.object)params.set('object',c.object);for(const key of ['tab','node','table','mode','step'])if(c[key]!==undefined)params.set(key,String(c[key]));if(c.analysis)params.set('analysis',JSON.stringify(c.analysis));if(user.role==='teacher')sessionStorage.setItem(teachingKey(),JSON.stringify({person:result.participant,group:result.group}));location.hash=c.route+'?'+params;}

function projectStartRoute(p){const entry=p?.lab_entry,route=entry==='graph'&&flags.graph?'graph':entry==='dataset'&&flags.data_lab?'data-lab':['prompt','rag','network'].includes(entry)&&(flags.ai||flags.rag||flags.neural)?'ai-lab':flags.editor?'editor':'files';return route+(p?.id?'?project='+p.id:'');}
